// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 amount) public {
        // Ensure amount is reasonable (avoid overflow issues)
        vm.assume(amount > 0 && amount <= 1e18);

        // Record initial betLimit (should be 0 from constructor)
        uint256 initialBetLimit = c.currentBetLimit();

        // Call AdjustBetAmounts as the owner (this is the deployer, address(this))
        c.AdjustBetAmounts(amount);

        // After owner call, betLimit should be amount
        assertTrue(c.currentBetLimit() == amount, "Owner call did not set betLimit correctly");
    }
}

